class Solution:
    def totalNQueens(self, n: int) -> int:
        full = (1 << n) - 1

        def bt(cols, d1, d2):
            if cols == full:
                return 1
            count, free = 0, ~(cols | d1 | d2) & full
            while free:
                bit = free & -free
                free -= bit
                count += bt(cols | bit, ((d1 | bit) << 1) & full, (d2 | bit) >> 1)
            return count

        return bt(0, 0, 0)

