class Solution {
    private int full;

    public int totalNQueens(int n) {
        full = (1 << n) - 1;
        return bt(0, 0, 0);
    }

    private int bt(int cols, int d1, int d2) {
        if (cols == full) return 1;
        int count = 0;
        for (int free = ~(cols | d1 | d2) & full; free != 0; ) {
            int bit = free & -free;
            free -= bit;
            count += bt(cols | bit, ((d1 | bit) << 1) & full, (d2 | bit) >> 1);
        }
        return count;
    }
}

